191	int main(int argc, char** argv) {
192	  using namespace andes_sim;
193	
194	  Cli cli = parse_cli(argc, argv);
195	  if (!cli.error.empty()) {
196	    std::fprintf(stderr, "andesim: %s\n", cli.error.c_str());
197	    return 2;
198	  }
199	
200	  if (!set_log_threshold(cli.log_level)) {
201	    std::fprintf(stderr,
202	                 "andesim: invalid --log-level '%s' (0=trace 1=debug 2=info "
203	                 "3=warn 4=error 5=critical 6=off)\n",
204	                 cli.log_level.c_str());
205	    return 2;
206	  }
207	  if (!set_log_file(cli.log_file)) {
208	    std::fprintf(stderr, "andesim: cannot open --log-file '%s' for append\n",
209	                 cli.log_file.c_str());
210	    return 2;
211	  }
212	
213	  if (cli.subcommand.empty()) {  // no command, or top-level -h
214	    if (cli.help) {
215	      print_usage(stdout);
216	      return 0;
217	    }
218	    print_usage(stderr);
219	    return 2;
220	  }
221	
222	  if (cli.help) {
223	    print_subcommand_help(cli.subcommand, stdout);
224	    return 0;
225	  }
226	
227	  if (cli.subcommand == "list") return cmd_list(cli);
228	  if (cli.subcommand == "doctor") return cmd_doctor(cli);
229	  if (cli.subcommand == "profile") return cmd_profile(cli);
230	  return cmd_run(cli);  // parse_cli admits only run/list/doctor/profile
231	}
